css:
.aha-testimonials{
  --aha-testimonials-surface:var(--aha-white);
  --aha-testimonials-hooks:var(--aha-vivid-pink-dark);
  --aha-testimonials-ink:var(--aha-text-default);
  --aha-testimonials-ink-muted:var(--aha-text-secondary);
  --aha-testimonials-ink-faint:var(--aha-text-tertiary);
  --aha-testimonials-star:var(--aha-color-primary);
  --aha-testimonials-focus:var(--aha-focus);
  --aha-testimonials-cta-bg:var(--aha-button-primary-bg);
  --aha-testimonials-cta-bg-hover:var(--aha-button-primary-bg-hover);
  --aha-testimonials-cta-text:var(--aha-button-primary-text);
  container:aha-testimonials / inline-size;
  position:relative;isolation:isolate;overflow:hidden;
  font-family:var(--aha-font-product);
  background:var(--aha-white);
  color:var(--aha-testimonials-ink);
}
.aha-testimonials--pink{
  --aha-testimonials-surface:var(--aha-vivid-pink-100);
  --aha-testimonials-ink:var(--aha-text-inverse);
  --aha-testimonials-ink-muted:var(--aha-text-inverse);
  --aha-testimonials-ink-faint:var(--aha-text-inverse);
  --aha-testimonials-star:var(--aha-white);
  --aha-testimonials-focus:var(--aha-white);
  --aha-testimonials-cta-bg:var(--aha-white);
  --aha-testimonials-cta-bg-hover:var(--aha-white);
  --aha-testimonials-cta-text:var(--aha-color-primary);
}
.aha-testimonials--pale{
  --aha-testimonials-surface:var(--aha-vivid-pink-5);
  --aha-testimonials-hooks:var(--aha-vivid-pink-5);
}
.aha-testimonials *{box-sizing:border-box}
:where(.aha-testimonials) h2,:where(.aha-testimonials) h3,:where(.aha-testimonials) p,:where(.aha-testimonials) blockquote,:where(.aha-testimonials) figure,:where(.aha-testimonials) ul{margin:0;padding:0}
:where(.aha-testimonials) ul{list-style:none}
.aha-testimonials__surface{position:absolute;inset:0;z-index:-1;overflow:hidden;background:var(--aha-testimonials-surface)}
.aha-testimonials__hooks{
  position:absolute;left:75%;top:55%;width:180cqw;height:auto;
  transform:translate(-51.6%,-42.6%);
  fill:var(--aha-testimonials-hooks);
}
.aha-testimonials__inner{
  display:flex;flex-direction:column;gap:var(--aha-space-48);
  width:100%;max-width:1280px;margin:0 auto;
  padding:var(--aha-space-96) var(--aha-space-64);
}

.aha-testimonials__stars{display:flex;gap:var(--aha-space-2);color:var(--aha-testimonials-star)}
.aha-testimonials__quote{
  font-size:var(--aha-size-h6);font-weight:var(--aha-weight-regular);
  line-height:var(--aha-line-height-body);letter-spacing:var(--aha-letter-spacing-paragraph);
  color:var(--aha-testimonials-ink);
}
.aha-testimonials__quote--large{
  font-size:var(--aha-size-h3);font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);letter-spacing:var(--aha-letter-spacing-headlines);
}
.aha-testimonials__quote--card{font-size:var(--aha-size-h6)}
.aha-testimonials__avatar{
  display:block;flex:none;object-fit:cover;
  width:var(--aha-space-44);height:var(--aha-space-44);
  border-radius:var(--aha-radius-pill);background:var(--aha-bg-accent);
}
.aha-testimonials__avatar--xl{width:var(--aha-space-64);height:var(--aha-space-64)}
.aha-testimonials__person{display:flex;align-items:center;gap:var(--aha-space-12)}
.aha-testimonials__person-text{display:flex;flex-direction:column}
.aha-testimonials__name{font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);color:var(--aha-testimonials-ink)}
.aha-testimonials__role{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-testimonials-ink-faint)}
.aha-testimonials__caption{display:flex;flex-direction:column;align-items:center;gap:var(--aha-space-4)}
.aha-testimonials__caption>.aha-testimonials__avatar{margin-bottom:var(--aha-space-12)}
.aha-testimonials__caption .aha-testimonials__stars{margin-top:var(--aha-space-12)}
.aha-testimonials__caption--row{flex-direction:row;align-items:center;gap:var(--aha-space-12)}
.aha-testimonials__caption--row>.aha-testimonials__avatar{margin-bottom:0}
.aha-testimonials__logo{display:block;width:auto;max-width:100%;height:var(--aha-space-64);filter:saturate(0)}
.aha-testimonials--pink .aha-testimonials__logo{filter:saturate(0) brightness(0) invert(1)}
.aha-testimonials--pink .aha-testimonials__panel .aha-testimonials__logo{filter:saturate(0)}
.aha-testimonials__logo--top{margin:0 auto var(--aha-space-8)}
.aha-testimonials__logo--left{margin:0 0 var(--aha-space-8)}
.aha-testimonials__logos{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:var(--aha-space-32) var(--aha-space-48)}
.aha-testimonials__title{
  font-size:var(--aha-size-h3);font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-testimonials-ink);
}
.aha-testimonials__lead{margin-top:var(--aha-space-12);font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-testimonials-ink-muted)}
.aha-testimonials__text{font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-testimonials__header{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--aha-space-32)}
.aha-testimonials__header--center{flex-direction:column;align-items:center;text-align:center}
.aha-testimonials__header-actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12)}
.aha-testimonials__button{
  display:flex;align-items:center;justify-content:center;
  height:var(--aha-control-height-button-lg);padding:0 var(--aha-space-20);
  border-radius:var(--aha-radius-default);
  font-size:var(--aha-size-l);font-weight:var(--aha-weight-regular);line-height:1;white-space:nowrap;text-decoration:none;
  color:var(--aha-testimonials-cta-text);background:var(--aha-testimonials-cta-bg);
  transition:background-color var(--aha-motion-mid),color var(--aha-motion-mid);
}
.aha-testimonials__button:hover,.aha-testimonials__button:active{background:var(--aha-testimonials-cta-bg-hover)}
.aha-testimonials__button--quiet{background:transparent;box-shadow:inset 0 0 0 1px var(--aha-testimonials-ink);color:var(--aha-testimonials-ink)}
.aha-testimonials__button--quiet:hover,.aha-testimonials__button--quiet:active{background:var(--aha-white-a50)}
.aha-testimonials__button:focus-visible{outline:var(--aha-space-2) solid var(--aha-testimonials-focus);outline-offset:var(--aha-space-2)}

.aha-testimonials__track{
  display:flex;gap:var(--aha-space-24);
  overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none; /* ds-lint-allow: overflow-x-scroll (swipeable carousel track, scrolled by the arrow buttons and arrow keys) */
}
.aha-testimonials__track::-webkit-scrollbar{display:none}
.aha-testimonials__track:focus-visible{outline:var(--aha-space-2) solid var(--aha-testimonials-focus);outline-offset:var(--aha-space-4)}
.aha-testimonials__slide{flex:0 0 100%;scroll-snap-align:start;min-width:0}
.aha-testimonials__slide--card{flex-basis:calc((100% - 2 * var(--aha-space-24)) / 3)}
.aha-testimonials__slide--glass{flex-basis:calc((100% - 3 * var(--aha-space-24)) / 4)}
.aha-testimonials__single{display:flex;flex-direction:column;align-items:center;gap:var(--aha-space-32);max-width:960px;margin:0 auto;text-align:center}
.aha-testimonials__arrows{display:flex;gap:var(--aha-space-12)}
.aha-testimonials__dots{display:flex;justify-content:center;gap:var(--aha-space-12)}
.aha-testimonials__dot{
  position:relative;width:var(--aha-space-12);height:var(--aha-space-12);padding:0;
  border:0;border-radius:var(--aha-radius-pill);cursor:pointer;
  background:transparent;box-shadow:inset 0 0 0 var(--aha-space-2) var(--aha-testimonials-ink);
  transition:background-color var(--aha-motion-mid);
}
.aha-testimonials__dot::after{content:"";position:absolute;inset:calc(-1 * var(--aha-space-6))}
.aha-testimonials__dot[aria-current="true"]{background:var(--aha-testimonials-ink)}
.aha-testimonials__dot:focus-visible{outline:var(--aha-space-2) solid var(--aha-testimonials-focus);outline-offset:var(--aha-space-2)}

.aha-testimonials__split-row{display:flex;align-items:center;gap:var(--aha-space-64);max-width:960px;margin:0 auto}
.aha-testimonials__split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:center;gap:var(--aha-space-64)}
.aha-testimonials__copy{display:flex;flex-direction:column;align-items:flex-start;gap:var(--aha-space-24)}
.aha-testimonials__foot{display:flex;align-items:center;justify-content:space-between;gap:var(--aha-space-24);width:100%}
.aha-testimonials__media{position:relative;overflow:hidden;border-radius:var(--aha-radius-marketing);background:var(--aha-bg-container-secondary)}
.aha-testimonials__photo{display:block;width:100%;height:auto;object-fit:cover;border-radius:var(--aha-radius-marketing);background:var(--aha-bg-container-secondary)}
.aha-testimonials__media .aha-testimonials__photo{border-radius:0;aspect-ratio:4 / 5}
.aha-testimonials__photo--square{flex:none;width:240px;aspect-ratio:1 / 1}
.aha-testimonials__overlay{
  position:absolute;left:var(--aha-space-16);right:var(--aha-space-16);bottom:var(--aha-space-16);
  display:flex;align-items:center;justify-content:space-between;gap:var(--aha-space-16);
  padding:var(--aha-space-16) var(--aha-space-20);
  border-radius:var(--aha-radius-lg);background:var(--aha-white-a90);
  color:var(--aha-text-default);
}
.aha-testimonials__overlay .aha-testimonials__name{color:var(--aha-text-default)}
.aha-testimonials__overlay .aha-testimonials__role{color:var(--aha-text-secondary)}
.aha-testimonials__overlay .aha-testimonials__stars{color:var(--aha-color-primary)}

.aha-testimonials__panel{
  display:flex;flex-direction:column;gap:var(--aha-space-32);
  max-width:960px;margin:0 auto;padding:var(--aha-space-64);text-align:center;
  border-radius:var(--aha-radius-marketing);
  background:var(--aha-bg-container-secondary);color:var(--aha-text-default);
  --aha-testimonials-ink:var(--aha-text-default);--aha-testimonials-ink-faint:var(--aha-text-tertiary);--aha-testimonials-star:var(--aha-color-primary);
}
.aha-testimonials--pink .aha-testimonials__panel{background:var(--aha-white)}
.aha-testimonials__panel--split{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);align-items:stretch;gap:0;max-width:1120px;padding:0;overflow:hidden;text-align:left}
.aha-testimonials__panel--split .aha-testimonials__photo{height:100%;border-radius:0;aspect-ratio:4 / 5}
.aha-testimonials__panel--split .aha-testimonials__copy{justify-content:center;padding:var(--aha-space-64)}

.aha-testimonials__card{
  position:relative;display:flex;flex-direction:column;
  height:100%;
  background:var(--aha-bg-container);color:var(--aha-text-default);
  border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-marketing);overflow:hidden;
}
.aha-testimonials__cover{aspect-ratio:3 / 2;background:var(--aha-bg-container-secondary);overflow:hidden}
.aha-testimonials__cover-image{display:block;width:100%;height:100%;object-fit:cover}
.aha-testimonials__card-body{display:flex;flex:1;flex-direction:column;align-items:flex-start;gap:var(--aha-space-12);padding:var(--aha-space-24)}
.aha-testimonials__card-title{font-size:var(--aha-size-xl);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-testimonials__link{color:inherit;text-decoration:none}
.aha-testimonials__link::after{content:"";position:absolute;inset:0}
.aha-testimonials__link:focus-visible{outline:none}
.aha-testimonials__card:has(.aha-testimonials__link:focus-visible){outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-testimonials__card .aha-testimonials__name{color:var(--aha-text-default)}
.aha-testimonials__card .aha-testimonials__role{color:var(--aha-text-tertiary)}
.aha-testimonials__more{display:inline-flex;align-items:center;gap:var(--aha-space-8);margin-top:auto;font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-testimonials__card--linked{transition:transform var(--aha-motion-mid) var(--aha-ease-out),box-shadow var(--aha-motion-mid) var(--aha-ease-out),border-color var(--aha-motion-mid) var(--aha-ease-out)}
.aha-testimonials__card--linked:hover{transform:translateY(calc(-1 * var(--aha-space-4)));border-color:var(--aha-border-hover);box-shadow:0 var(--aha-space-12) var(--aha-space-24) var(--aha-ink-a10)}
.aha-testimonials__card--linked:hover .aha-testimonials__more{color:var(--aha-text-link-hover)}

.aha-testimonials__glass{
  position:relative;
  overflow:hidden;border-radius:var(--aha-radius-marketing);background:var(--aha-bg-container-secondary);
}
.aha-testimonials__glass-photo{display:block;width:100%;aspect-ratio:3 / 4;height:auto;object-fit:cover}
.aha-testimonials__glass-panel{
  position:absolute;left:var(--aha-space-12);right:var(--aha-space-12);bottom:var(--aha-space-12);
  display:flex;flex-direction:column;gap:var(--aha-space-12);
  padding:var(--aha-space-16);border-radius:var(--aha-radius-lg);
  background:var(--aha-white-a90);
  color:var(--aha-text-default);
  --aha-testimonials-ink:var(--aha-text-default);--aha-testimonials-ink-faint:var(--aha-text-secondary);--aha-testimonials-star:var(--aha-color-primary);
}
@supports (backdrop-filter:blur(1px)){
  .aha-testimonials__glass-panel{background:var(--aha-white-a70);-webkit-backdrop-filter:blur(var(--aha-space-16));backdrop-filter:blur(var(--aha-space-16))}
}
.aha-testimonials__glass-panel .aha-testimonials__quote{font-size:var(--aha-size-default)}
.aha-testimonials--glass-1 .aha-testimonials__glass-photo{aspect-ratio:3 / 5;object-position:top}
.aha-testimonials--glass-2 .aha-testimonials__glass-photo{aspect-ratio:2 / 3}
.aha-testimonials--glass-2 .aha-testimonials__glass-panel .aha-testimonials__quote{font-size:var(--aha-size-xl);font-weight:var(--aha-weight-semibold)}
.aha-testimonials--glass-2 .aha-testimonials__slide--glass{flex-basis:calc((100% - 2 * var(--aha-space-24)) / 3)}

.aha-testimonials__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--aha-space-24);align-items:start}
.aha-testimonials__grid--columns>li{display:flex;flex-direction:column;gap:var(--aha-space-24)}
.aha-testimonials__grid--wall{align-items:stretch}
.aha-testimonials__post{
  display:flex;flex-direction:column;gap:var(--aha-space-16);height:100%;padding:var(--aha-space-24);
  background:var(--aha-bg-container);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-marketing);
  --aha-testimonials-ink:var(--aha-text-default);--aha-testimonials-ink-faint:var(--aha-text-tertiary);
}
.aha-testimonials__post-head{display:flex;align-items:center;gap:var(--aha-space-12)}
.aha-testimonials__post-head .aha-testimonials__person-text{flex:1;min-width:0}
.aha-testimonials__network{display:block;flex:none;width:var(--aha-space-24);height:var(--aha-space-24)}
.aha-testimonials__post-text{font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-default)}
.aha-testimonials__post-image{display:block;width:100%;height:auto;aspect-ratio:3 / 2;object-fit:cover;border-radius:var(--aha-radius-lg)}

.aha-testimonials__split--abstract{align-items:center}
.aha-testimonials__collage{position:relative;width:100%;aspect-ratio:1 / 1;max-width:560px;margin-left:auto}
.aha-testimonials__tile{position:absolute;overflow:hidden;border-radius:var(--aha-radius-lg);background:var(--aha-bg-container-secondary)}
.aha-testimonials__tile-image{display:block;width:100%;height:100%;object-fit:cover}
.aha-testimonials__tile--1{left:0;top:6%;width:34%;height:40%}
.aha-testimonials__tile--2{left:38%;top:0;width:30%;height:34%}
.aha-testimonials__tile--3{left:72%;top:10%;width:28%;height:32%}
.aha-testimonials__tile--4{left:12%;top:52%;width:34%;height:42%}
.aha-testimonials__tile--5{left:52%;top:46%;width:42%;height:48%}

@media (prefers-reduced-motion:reduce){
  .aha-testimonials__card--linked,.aha-testimonials__dot,.aha-testimonials__button{transition:none}
  .aha-testimonials__card--linked:hover{transform:none}
}
@container aha-testimonials (max-width:991px){
  .aha-testimonials__hooks{width:450cqw}
  .aha-testimonials__inner{padding:var(--aha-space-64) var(--aha-space-32);gap:var(--aha-space-40)}
  .aha-testimonials__quote--large,.aha-testimonials__title{font-size:var(--aha-size-h4)}
  .aha-testimonials__split,.aha-testimonials--abstract .aha-testimonials__split{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-40)}
  .aha-testimonials__panel{padding:var(--aha-space-40)}
  .aha-testimonials__panel--split{grid-template-columns:minmax(0,1fr)}
  .aha-testimonials__panel--split .aha-testimonials__photo{aspect-ratio:3 / 2}
  .aha-testimonials__panel--split .aha-testimonials__copy{padding:var(--aha-space-40)}
  .aha-testimonials__slide--card,.aha-testimonials__slide--glass,.aha-testimonials--glass-2 .aha-testimonials__slide--glass{flex-basis:calc((100% - var(--aha-space-24)) / 2)}
  .aha-testimonials__grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-testimonials__grid--columns{grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-testimonials__collage{margin:0 auto}
  .aha-testimonials__header{flex-direction:column;align-items:flex-start}
}
@container aha-testimonials (max-width:767px){
  .aha-testimonials__split-row{flex-direction:column;align-items:flex-start;gap:var(--aha-space-32)}
  .aha-testimonials__photo--square{width:var(--aha-space-100)}
  .aha-testimonials__slide--card,.aha-testimonials__slide--glass,.aha-testimonials--glass-2 .aha-testimonials__slide--glass{flex-basis:100%}
  .aha-testimonials__grid,.aha-testimonials__grid--columns{grid-template-columns:minmax(0,1fr)}
}
@container aha-testimonials (max-width:479px){
  .aha-testimonials__inner{padding:var(--aha-space-48) var(--aha-space-16);gap:var(--aha-space-32)}
  .aha-testimonials__quote--large,.aha-testimonials__title{font-size:var(--aha-size-h6)}
  .aha-testimonials__panel,.aha-testimonials__panel--split .aha-testimonials__copy{padding:var(--aha-space-24)}
  .aha-testimonials__foot{flex-direction:column;align-items:flex-start}
  .aha-testimonials__overlay{flex-direction:column;align-items:flex-start}
}
